# ============================================================
# AEGIS NIDS - Phase 23.3 Combined Patch (ALL compilation + test fixes)
# ============================================================
$ErrorActionPreference = 'Stop'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS Phase 23.3 - ALL fixes combined (13 errors)"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"

function Deploy-File {
    param([string]$RelativePath, [string]$Base64Content, [int]$ExpectedLines)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $BackupPath = "$FullPath.phase23_3_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    Write-Host "  [OK] $((Get-Content $FullPath).Count) lines"
}

$B64_1 = ''
Deploy-File -RelativePath "core/nids_analyze.zig" -ExpectedLines 2166 -Base64Content $B64_1

$B64_2 = ''
Deploy-File -RelativePath "core/wfp_ioctl.zig" -ExpectedLines 585 -Base64Content $B64_2

$B64_3 = ''
Deploy-File -RelativePath "core/forensic_log.zig" -ExpectedLines 433 -Base64Content $B64_3

$B64_4 = ''
Deploy-File -RelativePath "core/win32_io.zig" -ExpectedLines 166 -Base64Content $B64_4

$B64_5 = ''
